<div class="form-two"><div><label>Business name</label><input name="name" value="{{old('name',$business->name??'')}}" maxlength="100" required></div><div><label>Business timezone</label><input name="timezone" value="{{old('timezone',$business->timezone??'Europe/London')}}" placeholder="Europe/London" required><p class="caption">Use an IANA timezone, for example Europe/London.</p></div></div>
<div class="form-two"><div><label>Primary contact name</label><input name="contact_name" value="{{old('contact_name',$profile->contact_name??'')}}" maxlength="100"></div><div><label>Contact email</label><input name="contact_email" type="email" value="{{old('contact_email',$profile->contact_email??'')}}" maxlength="255"></div></div>
<div class="form-two"><div><label>Contact phone</label><input name="contact_phone" value="{{old('contact_phone',$profile->contact_phone??'')}}" maxlength="40"></div><div><label>Website (HTTPS)</label><input name="website" type="url" value="{{old('website',$profile->website??'')}}" placeholder="https://" maxlength="255"></div></div>
